    ('xNrS20v', 'Barbell Reverse Curl', '{biceps}', '{forearms}', 'barbell', 'https://static.exercisedb.dev/media/xNrS20v.gif', array['Stand up straight with your feet shoulder-width apart and hold a barbell with an overhand grip, palms facing down.', 'Keep your upper arms stationary and exhale as you curl the barbell upward, contracting your biceps.', 'Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level.', 'Hold the contracted position for a brief pause as you squeeze your biceps.', 'Inhale as you slowly lower the barbell back to the starting position, keeping your upper arms stationary.', 'Repeat for the desired number of repetitions.']),
    ('qXTaZnJ', 'Barbell Full Squat', '{glutes}', '{quads,hamstrings,calves,abs}', 'barbell', 'https://static.exercisedb.dev/media/qXTaZnJ.gif', array['Stand with your feet shoulder-width apart, toes slightly turned out.', 'Hold the barbell across your upper back, resting it on your traps or rear delts.', 'Engage your core and keep your chest up as you begin to lower your body down.', 'Bend at the knees and hips, pushing your hips back and down as if sitting into a chair.', 'Lower yourself until your thighs are parallel to the ground or slightly below.', 'Keep your knees in line with your toes and your weight in your heels.', 'Drive through your heels to stand back up, extending your hips and knees.', 'Repeat for the desired number of repetitions.']),
    ('zG0zs85', 'Barbell Front Squat', '{glutes}', '{quads,hamstrings,calves,abs}', 'barbell', 'https://static.exercisedb.dev/media/zG0zs85.gif', array['Start by standing with your feet shoulder-width apart, toes slightly turned out.', 'Hold the barbell in front of your shoulders, resting it on your collarbone and shoulders.', 'Engage your core and keep your chest up as you lower your body down into a squat position, pushing your hips back and bending your knees.', 'Lower until your thighs are parallel to the ground, or as low as you can comfortably go.', 'Pause for a moment at the bottom, then push through your heels to return to the starting position.', 'Repeat for the desired number of repetitions.']),
    ('yn8yg1r', 'Dumbbell Goblet Squat', '{quads}', '{glutes,hamstrings,calves}', 'dumbbell', 'https://static.exercisedb.dev/media/yn8yg1r.gif', array['Stand with your feet shoulder-width apart, holding a dumbbell vertically against your chest with both hands.', 'Keeping your chest up and core engaged, lower your body down into a squat position by pushing your hips back and bending your knees.', 'Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.', 'Pause for a moment at the bottom, then push through your heels to return to the starting position.', 'Repeat for the desired number of repetitions.']),
    ('2Qh2J1e', 'Sled 45° Leg Press (Side Pov)', '{glutes}', '{quads,hamstrings,calves}', 'machine', 'https://static.exercisedb.dev/media/2Qh2J1e.gif', array['Adjust the seat of the sled machine so that your knees are at a 90-degree angle when your feet are on the footplate.', 'Sit on the sled machine with your back flat against the backrest and your feet shoulder-width apart on the footplate.', 'Grip the handles on the sides of the seat for stability.', 'Push against the footplate to extend your legs, straightening them completely.', 'Pause for a moment at the top, then slowly bend your knees to lower the footplate back to the starting position.', 'Repeat for the desired number of repetitions.']),
    ('Qa55kX1', 'Sled Hack Squat', '{glutes}', '{quads,hamstrings,calves}', 'machine', 'https://static.exercisedb.dev/media/Qa55kX1.gif', array['Adjust the sled machine to a comfortable position for your height.', 'Stand with your feet shoulder-width apart on the platform, toes slightly pointed outwards.', 'Hold onto the handles or bars for stability.', 'Lower your body by bending your knees and hips, keeping your back straight and chest up.', 'Continue lowering until your thighs are parallel to the ground or slightly below.', 'Pause for a moment, then push through your heels to raise your body back up to the starting position.', 'Repeat for the desired number of repetitions.']),
    ('qx4fgX7', 'Dumbbell Single Leg Split Squat', '{quads}', '{glutes,hamstrings,calves}', 'dumbbell', 'https://static.exercisedb.dev/media/qx4fgX7.gif', array['Stand with your feet shoulder-width apart, holding a dumbbell in each hand.', 'Take a step forward with one foot and position your feet so that your front foot is flat on the ground and your back foot is elevated on a bench or step.', 'Lower your body by bending your front knee and hip, keeping your back knee slightly bent and your back heel off the ground.', 'Continue lowering until your front thigh is parallel to the ground, then push through your front heel to return to the starting position.', 'Repeat for the desired number of repetitions, then switch legs and repeat.']),
    ('IZVHb27', 'Walking Lunge', '{glutes}', '{quads,hamstrings,calves}', 'bodyweight', 'https://static.exercisedb.dev/media/IZVHb27.gif', array['Stand with your feet shoulder-width apart.', 'Take a step forward with your right leg, lowering your body into a lunge position.', 'Keep your torso upright and your front knee aligned with your ankle.', 'Push off with your right foot and bring your left foot forward, stepping into a lunge position with your left leg.', 'Continue alternating legs and walking forward, maintaining a controlled and steady pace.', 'Repeat for the desired number of repetitions.']),
    ('aXtJhlg', 'Dumbbell Step-Up', '{glutes}', '{quads,hamstrings,calves}', 'dumbbell', 'https://static.exercisedb.dev/media/aXtJhlg.gif', array['Stand in front of a bench or step with a dumbbell in each hand, palms facing your body.', 'Place your right foot on the bench or step, ensuring your entire foot is in contact with the surface.', 'Push through your right heel and lift your body up onto the bench or step, straightening your right leg.', 'Bring your left foot up onto the bench or step, standing fully upright.', 'Step back down with your left foot, followed by your right foot, returning to the starting position.', 'Repeat for the desired number of repetitions, then switch legs.']),
    ('my33uHU', 'Lever Leg Extension', '{quads}', '{hamstrings}', 'machine', 'https://static.exercisedb.dev/media/my33uHU.gif', array['Adjust the seat height and backrest of the machine to fit your body.', 'Sit on the machine with your back against the backrest and your feet on the footpad.', 'Grasp the handles or sidebars for stability.', 'Extend your legs forward by straightening your knees, lifting the weight.', 'Pause for a moment at the top, then slowly lower the weight back to the starting position.', 'Repeat for the desired number of repetitions.']),
    ('wQ2c4XD', 'Barbell Romanian Deadlift', '{glutes}', '{hamstrings,lower_back}', 'barbell', 'https://static.exercisedb.dev/media/wQ2c4XD.gif', array['Stand with your feet shoulder-width apart and your toes pointing forward.', 'Hold the barbell with an overhand grip, hands slightly wider than shoulder-width apart.', 'Bend at the hips, keeping your back straight and your knees slightly bent.', 'Lower the barbell towards the ground, keeping it close to your body.', 'Feel the stretch in your hamstrings as you lower the barbell.', 'Once you feel a stretch in your hamstrings, push your hips forward and stand up straight.', 'Squeeze your glutes at the top of the movement.', 'Lower the barbell back down to the starting position and repeat for the desired number of repetitions.']),
    ('XlZ4lAC', 'Barbell Good Morning', '{hamstrings}', '{lower_back}', 'barbell', 'https://static.exercisedb.dev/media/XlZ4lAC.gif', array['Start by standing with your feet shoulder-width apart and the barbell resting on your upper back.', 'Keeping your back straight and your core engaged, hinge forward at the hips, pushing your buttocks back as if you were trying to touch the wall behind you with your glutes.', 'Lower your torso until it is parallel to the ground, feeling a stretch in your hamstrings.', 'Pause for a moment, then return to the starting position by squeezing your glutes and pushing your hips forward.', 'Repeat for the desired number of repetitions.']),
    ('17lJ1kr', 'Lever Lying Leg Curl', '{hamstrings}', '{calves}', 'machine', 'https://static.exercisedb.dev/media/17lJ1kr.gif', array['Adjust the machine to fit your body and select the desired weight.', 'Lie face down on the machine with your legs straight and your heels against the padded lever.', 'Grasp the handles or the sides of the machine for stability.', 'Keeping your upper body stationary, exhale and curl your legs up as far as possible without lifting your hips off the pad.', 'Hold the contracted position for a brief pause as you squeeze your hamstrings.', 'Inhale and slowly lower the lever back to the starting position.', 'Repeat for the desired number of repetitions.']),
    ('Zg3XY7P', 'Lever Seated Leg Curl', '{hamstrings}', '{calves}', 'machine', 'https://static.exercisedb.dev/media/Zg3XY7P.gif', array['Adjust the machine to fit your body and sit on it with your back against the backrest.', 'Place your lower legs under the padded lever, just above your ankles.', 'Grasp the handles on the sides of the machine for support.', 'Keeping your upper legs stationary, exhale and curl your legs up as far as possible.', 'Hold the contracted position for a brief pause as you squeeze your hamstrings.', 'Inhale and slowly lower the lever back to the starting position.', 'Repeat for the desired number of repetitions.']),
    ('qKBpF7I', 'Barbell Glute Bridge', '{glutes}', '{hamstrings,lower_back}', 'barbell', 'https://static.exercisedb.dev/media/qKBpF7I.gif', array['Start by lying flat on your back on the ground with your knees bent and feet flat on the floor.', 'Place a barbell across your hips, holding it securely with both hands.', 'Engage your glutes and core muscles, then lift your hips off the ground until your body forms a straight line from your knees to your shoulders.', 'Pause for a moment at the top, squeezing your glutes.', 'Slowly lower your hips back down to the starting position.', 'Repeat for the desired number of repetitions.']),
    ('UHJlbu3', 'Kettlebell Swing', '{glutes}', '{hamstrings,abs}', 'kettlebell', 'https://static.exercisedb.dev/media/UHJlbu3.gif', array['Stand with your feet shoulder-width apart, toes pointed slightly outward.', 'Hold the kettlebell with both hands in front of your body, arms extended.', 'Bend your knees slightly and hinge at the hips, pushing your butt back.', 'Swing the kettlebell back between your legs, keeping your arms straight and maintaining a flat back.', 'Drive your hips forward and swing the kettlebell up to shoulder height, using the momentum generated by your hips.', 'Allow the kettlebell to swing back down between your legs and repeat the movement for the desired number of repetitions.']),
    ('oHsrypV', 'Lever Seated Hip Adduction', '{adductors}', '{hamstrings,glutes}', 'machine', 'https://static.exercisedb.dev/media/oHsrypV.gif', array['Adjust the seat height and position yourself on the machine with your back against the backrest.', 'Place your feet on the footrests and grasp the handles for stability.', 'Engage your adductor muscles and slowly bring your legs together, squeezing your inner thighs.', 'Pause for a moment at the peak contraction, then slowly return to the starting position.', 'Repeat for the desired number of repetitions.']),
    ('CHpahtl', 'Lever Seated Hip Abduction', '{abductors}', '{glutes,hamstrings}', 'machine', 'https://static.exercisedb.dev/media/CHpahtl.gif', array['Adjust the seat height so that your knees are at a 90-degree angle.', 'Sit on the machine with your back against the backrest and your feet on the footrests.', 'Place your hands on the side handles for stability.', 'Engage your abductors and slowly push your legs apart, away from the midline of your body.', 'Pause for a moment at the end of the movement, then slowly bring your legs back together to the starting position.', 'Repeat for the desired number of repetitions.']),
    ('8ozhUIZ', 'Barbell Standing Calf Raise', '{calves}', '{hamstrings,glutes}', 'barbell', 'https://static.exercisedb.dev/media/8ozhUIZ.gif', array['Stand with your feet shoulder-width apart and place a barbell across your upper back.', 'Raise your heels off the ground as high as possible, using only your toes.', 'Pause for a moment at the top, then slowly lower your heels back down to the starting position.', 'Repeat for the desired number of repetitions.']),
    ('bOOdeyc', 'Lever Seated Calf Raise', '{calves}', '{}', 'machine', 'https://static.exercisedb.dev/media/bOOdeyc.gif', array['Adjust the seat height so that your knees are slightly bent and your feet are flat on the footplate.', 'Place your toes on the footplate with your heels hanging off the edge.', 'Grasp the handles or the sides of the seat for stability.', 'Push through the balls of your feet to raise your heels as high as possible.', 'Pause for a moment at the top, then slowly lower your heels back down to the starting position.', 'Repeat for the desired number of repetitions.']),
    ('I3tsCnC', 'Hanging Leg Raise', '{abs}', '{}', 'bodyweight', 'https://static.exercisedb.dev/media/I3tsCnC.gif', array['Hang from a pull-up bar with your arms fully extended and your palms facing away from you.', 'Engage your core and lift your legs up in front of you, keeping them straight.', 'Continue lifting until your legs are parallel to the ground or as high as you can comfortably go.', 'Pause for a moment at the top, then slowly lower your legs back down to the starting position.', 'Repeat for the desired number of repetitions.']),
    ('8xUv4J7', 'Cable Seated Crunch', '{abs}', '{obliques}', 'cable', 'https://static.exercisedb.dev/media/8xUv4J7.gif', array['Sit on a cable machine with your feet flat on the ground and your knees bent.', 'Hold the cable handle with both hands and position it behind your head.', 'Engage your abs and slowly curl your upper body forward, bringing your chest towards your knees.', 'Pause for a moment at the top, then slowly return to the starting position.', 'Repeat for the desired number of repetitions.']),
    ('TFqbd8t', 'Crunch Floor', '{abs}', '{}', 'bodyweight', 'https://static.exercisedb.dev/media/TFqbd8t.gif', array['Lie flat on your back with your knees bent and feet flat on the ground.', 'Place your hands behind your head with your elbows pointing outwards.', 'Engage your abs and lift your shoulders off the ground, curling forward towards your knees.', 'Pause for a moment at the top, then slowly lower your shoulders back down to the starting position.', 'Repeat for the desired number of repetitions.']),
    ('NAgVB3t', 'Wheel Rollerout', '{abs}', '{lower_back}', 'other', 'https://static.exercisedb.dev/media/NAgVB3t.gif', array['Kneel on the floor and place the wheel roller in front of you.', 'Place your hands on the handles of the wheel roller and extend your arms straight out in front of you.', 'Engage your core muscles and slowly roll the wheel forward, keeping your back straight and your abs tight.', 'Continue rolling forward until your body is fully extended and your arms are overhead.', 'Pause for a moment, then slowly roll the wheel back towards your knees, maintaining control and keeping your abs engaged.', 'Repeat for the desired number of repetitions.']),
    ('XVDdcoj', 'Russian Twist', '{abs}', '{obliques}', 'bodyweight', 'https://static.exercisedb.dev/media/XVDdcoj.gif', array['Sit on the ground with your knees bent and feet flat on the floor.', 'Lean back slightly while keeping your back straight and your core engaged.', 'Hold your hands together in front of your chest or hold a weight if desired.', 'Lift your feet off the ground, balancing on your sit bones.', 'Twist your torso to the right, bringing your hands or weight towards the right side of your body.', 'Pause for a moment, then twist your torso to the left, bringing your hands or weight towards the left side of your body.', 'Continue alternating sides for the desired number of repetitions.']),
    ('aVs3BR3', 'Cable Twist', '{abs}', '{obliques}', 'cable', 'https://static.exercisedb.dev/media/aVs3BR3.gif', array['Stand with your feet shoulder-width apart, facing the cable machine.', 'Hold the cable handle with both hands in front of your chest, keeping your arms slightly bent.', 'Engage your core and twist your torso to the right, pulling the cable across your body.', 'Pause for a moment at the end of the movement, feeling the contraction in your abs and obliques.', 'Slowly return to the starting position, resisting the cable''s pull.', 'Repeat the movement to the left side.', 'Continue alternating sides for the desired number of repetitions.'])
  ) as v (external_id, name, primary_muscles, secondary_muscles, equipment, image_url, instructions)
$$;

revoke all on function public.starter_exercise_catalog() from public, anon, authenticated;

-- Give every existing account the starter bank (no-op for a brand-new project).
select public.seed_starter_exercises(id) from auth.users;
